const fs=require('fs'),path=require('path');const root='.factory-cache/figma/latest';const read=p=>JSON.parse(fs.readFileSync(path.join(root,p),'utf8'));const write=(p,v)=>{const f=path.join(root,p);fs.mkdirSync(path.dirname(f),{recursive:true});fs.writeFileSync(f,JSON.stringify(v,null,2)+'\\n')};const f={\"nodeId\":\"326:2735\",\"value\":\"DZIA\\u0141ANIE NA CHWASTY\\nAQUATOS jest pobierany przez korzenie i cz\\u0119\\u015bci nadziemne chwast\\u00f3w.  Najskuteczniej zwalcza chwasty w okresie ich kie\\u0142kowania i wschod\\u00f3w.  Chwasty jednoli\\u015bcienne s\\u0105 zwalczane do fazy pierwszego lub do pocz\\u0105tku  drugiego li\\u015bcia, a chwasty dwuli\\u015bcienne do fazy dw\\u00f3ch li\\u015bci w\\u0142a\\u015bciwych.\\nChwasty wra\\u017cliwe: chwastnica jednostronna, fio\\u0142ek  polny, fiolek tr\\u00f3jbarwny, gwiazdnica pospolita, jasnota r\\u00f3\\u017cowa, komosa  bia\\u0142a, pokrzywa \\u017cegawka, przetacznik perski, rdest ptasi, rdest  plamisty, rzodkiew \\u015bwirzepa, rumian polny, tasznik pospolity, wiechlina  roczna.\\nChwasty \\u015brednio wra\\u017cliwe: bodziszek drobny, gorczyca polna, iglica pospolita, jasnota purpurowa, pokrzywa zwyczajna,  poziewnik szorstki, przytulia czepna, rdest\\u00f3wka powojowata (rdest  powojowaty), rumianek pospolity, szar\\u0142at szorstki, tobo\\u0142ki polne.  Chwasty \\u015brednio odporne: maruna bezwonna.\\nChwasty odporne: przymiotno kanadyjskie, starzec zwyczajny, szarota b\\u0142otna, \\u017c\\u00f3\\u0142tlica drobnokwiatowa.\\n\\nSTOSOWANIE \\u015aRODKA OCHRONY RO\\u015aLIN\\n\\nTRUSKAWKA\\nTermin stosowania: \\u015arodek stosowa\\u0107 jesieni\\u0105 lub wczesn\\u0105 wiosn\\u0105 (BBCH 93-00 ) na gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna dawka dla jednorazowego zastosowania: 3,5 l/ha.\\nZalecana dawka dla jednorazowego zastosowania: 2,5 \\u2013 3,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\n\\nCEBULA UPRAWIANA Z SIEWU\\nZabieg jednorazowy Termin stosowania: Opryskiwa\\u0107 bezpo\\u015brednio po  siewie (BBCH 00-01) lub po wschodach, gdy ro\\u015bliny cebuli znajduj\\u0105 si\\u0119 w  fazie 1-2 li\\u015bci w\\u0142a\\u015bciwych, (BBCH 10-12), na gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna dawka dla jednorazowego zastosowania: 3,5 l/ha.\\nZalecana dawka dla jednorazowego zastosowania: 2,5 \\u2013 3,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym (z uwzgl\\u0119dnieniem  zastosowa\\u0144 ma\\u0142oobszarowych wymienionych w dalszej cz\\u0119\\u015bci etykiety): 3.\\n\\nMARCHEW\\nZabieg jednorazowy. Termin stosowania: Opryskiwa\\u0107 do 5 dni po siewie, przed wschodami (BBCH 01-05) na gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna dawka dla jednorazowego zastosowania: 3,5 l/ha.\\nZalecana dawka dla jednorazowego zastosowania: 2,5 \\u2013 3,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym (z uwzgl\\u0119dnieniem  zastosowa\\u0144 ma\\u0142oobszarowych wymienionych w dalszej cz\\u0119\\u015bci etykiety): 2.\\n\\nGROCH JADALNY ZIELONY\\nTermin stosowania: Opryskiwa\\u0107 bezpo\\u015brednio po siewie, najp\\u00f3\\u017aniej do 3 dni (BBCH 00-01) na gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna dawka dla jednorazowego zastosowania: 3,5l/ha.\\nZalecana dawka dla jednorazowego zastosowania: 2,5 \\u2013 3,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym: 1. UWAGA: Nasiona wysiewa\\u0107 na jednakow\\u0105 g\\u0142\\u0119boko\\u015b\\u0107, nie mniejsz\\u0105 ni\\u017c 4-5 cm.\\n\\nCEBULA UPRAWIANA Z SIEWU\\nDawki dzielone.\\nPierwszy zabieg Termin stosowania: zabieg wykona\\u0107 bezpo\\u015brednio po siewie cebuli, ale przed wschodami cebuli (BBCH 00-01).\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 1,75 l/ha.\\nDrugi zabieg Termin stosowania: po wschodach cebuli, po przej\\u015bciu  fazy flagi i ukazaniu si\\u0119 pierwszego li\\u015bcia w\\u0142a\\u015bciwego (BBCH 11-16), na  gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 1,75 l/ha.\\nOdst\\u0119p pomi\\u0119dzy pierwszym i drugim zabiegiem: co najmniej 2-8  tygodni. Lub Pierwszy zabieg Termin stosowania bezpo\\u015brednio po siewie,  ale przed wschodami cebuli (BBCH 00-01).\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 1,2 l/ha.\\nDrugi zabieg Termin  stosowania: po wschodach cebuli, po przej\\u015bciu fazy flagi i ukazaniu si\\u0119  pierwszego li\\u015bcia w\\u0142a\\u015bciwego (BBCH 11-14), na gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 1,1 l/ha.\\nOdst\\u0119p pomi\\u0119dzy pierwszym i drugim zabiegiem: co najmniej 2-8 tygodni.\\nTrzeci zabieg Termin stosowania: po wschodach (BBCH 14-16), na gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 1,2 l/ha.\\nOdst\\u0119p pomi\\u0119dzy drugim i trzecim zabiegiem : co najmniej 1-6 tygodni.\\nUWAGA: \\u0141\\u0105czne dawki w zabiegach dzielonych nie mog\\u0105 przekracza\\u0107 3,5l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym (z uwzgl\\u0119dnieniem  zastosowa\\u0144 wymienionych we wcze\\u015bniejszej cz\\u0119\\u015bci etykiety): 3.\\n\\nCEBULA UPRAWIANA Z DYMKI\\nTermin stosowania: \\u015arodek stosowa\\u0107 do 5 dni po sadzeniu przy  wysoko\\u015bci szczypioru 5-10 cm, od fazy 1-2 li\\u015bci w\\u0142a\\u015bciwych (BBCH 11-12), na gleb\\u0119 woln\\u0105 od chwast\\u00f3w.\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 3,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym: 1.\\n\\nCEBULA UPRAWIANA Z ROZSADY\\nTermin stosowania: \\u015arodek stosowa\\u0107 w 5 -10 dni po sadzeniu, gdy rozsada w czasie sadzenia ma 1-2 li\\u015bcie w\\u0142a\\u015bciwe (BBCH11-12).\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 3,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym: 1.\\n\\nCZOSNEK\\nTermin stosowania: \\u015arodek stosowa\\u0107 po sadzeniu czosnku, ale przed  wschodami (BBCH 01-08) lub po wschodach czosnku przy wysoko\\u015bci ro\\u015blin  5-10 cm (BBCH 11-12) na gleb\\u0119 woln\\u0105 od chwast\\u00f3w. Z\\u0105bki czosnku sadzi\\u0107  nie p\\u0142ycej ni\\u017c na g\\u0142\\u0119boko\\u015b\\u0107 5 cm.\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 2,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-300 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym: 1.\\n\\nPOR UPRAWIANY Z SIEWU\\nTermin stosowania: \\u015arodek stosowa\\u0107 bezpo\\u015brednio po siewie (nie  p\\u00f3\\u017aniej ni\\u017c do 3 dni) (BBCH 00-01) lub po wschodach nie wcze\\u015bniej ni\\u017c od fazy 2 li\\u015bci w\\u0142a\\u015bciwych (BBCH 12), na gleb\\u0119 woln\\u0105 od chwast\\u00f3w\\nMaksymalna/zalecana dawka dla jednorazowego zastosowania: 3,5 l/ha.\\nZalecana ilo\\u015b\\u0107 wody: 200-400 l/ha.\\nZalecane opryskiwanie: \\u015bredniokropliste.\\nMaksymalna liczba zabieg\\u00f3w w sezonie wegetacyjnym: 1.\\nUWAGA: Nasiona pora wysiewa\\u0107 na jednakow\\u0105 g\\u0142\\u0119boko\\u015b\\u0107, nie mniejsz\\u0105 ni\\u017c 2 cm.\\n\\nPOR UPRAWIANY Z ROZSADY\\nTermin stosowania: \\u015arodek stosowa\\u0107 do 7 dni po posadzeniu rozsady  (BBCH 12-13), na gleb\\u0119 woln\\u0105 od chwast\\u00f3w. Rozsada pora w czasie sadzenia powinna mie\\u0107 nie mniej ni\\u017c 2-3 li